projectFiles.src/labels.mjs:
function composeLabel(parts) {
  return parts.filter(Boolean).join(" ");
}

export function labelFor(parts) {
  return composeLabel(parts);
}

projectFiles.tests/labels.test.mjs:
import test from "node:test";
import assert from "node:assert/strict";
import { labelFor } from "../src/labels.mjs";

test("formats the public label contract", () => {
  assert.equal(labelFor(["Ada", "Lovelace"]), "Ada Lovelace");
  assert.equal(labelFor(["Ada", ""]), "Ada");
});

