projectFiles.src/sequence.mjs:
export function canAdvance(from, to) {
  return to > from;
}

projectFiles.tests/sequence.test.mjs:
import test from "node:test";
import assert from "node:assert/strict";
import { canAdvance } from "../src/sequence.mjs";

test("accepts adjacent and arbitrary forward values", () => {
  assert.equal(canAdvance(0, 1), true);
  assert.equal(canAdvance(0, 3), true);
});

test("rejects non-forward values", () => {
  assert.equal(canAdvance(1, 0), false);
  assert.equal(canAdvance(1, 1), false);
});

